local ServicesTicker = {}
ServicesTicker.__index = ServicesTicker

local EVENTS = {
	Heartbeat = true,
	PostSimulation = true,
	PreAnimation = true,
	PreRender = true,
	PreSimulation = true,
	Stepped = true,
	RenderStepped = false, -- only client
}

function ServicesTicker.new(hostServices: { {} })
	local self = setmetatable({}, ServicesTicker)
	self._hostServices = hostServices or {}
	self._runService = game:GetService("RunService")
	self._runEvents = {}

	-- services that will be ticked
	self._services = {}

	-- initialize service tables
	for eventName, _ in EVENTS do
		self._services[eventName] = {}
	end

	-- register services
	for _, service in self._hostServices do
		for eventName, isServer in EVENTS do
			if service[eventName] then
				self._services[eventName][service] = {}
				self._runEvents[eventName] = isServer
			end
		end
	end

	return self
end

function ServicesTicker:Start(cancellationToken: CancellationToken)
	if cancellationToken and cancellationToken.IsCancellationRequested then
		return
	end

	if self._connections then
		return
	end

	self._connections = {}

	local isServer = self._runService:isServer()

	for eventName, serverEvent in self._runEvents do
		if isServer and not serverEvent then
			continue
		end

		self._connections[eventName] = self._runService[eventName]:Connect(function(deltaTime)
			local curTick = tick()
			for service, context in self._services[eventName] do
				-- 检查是否已经有记录的间隔时间
				if not context.interval then
					-- 第一次调用,检查返回值
					local result = service[eventName](service, deltaTime)
					if type(result) == "number" and result > 0 then
						-- 记录间隔时间
						self._services[eventName][service] = {
							interval = result,
							lastTick = curTick,
						}
					else
						-- 标记为每帧调用
						context.interval = false
					end
				else
					if not context.interval then
						service[eventName](service, deltaTime)
					else
						local delta = curTick - context.lastTick
						if delta >= context.interval then
							service[eventName](service, delta)
							context.lastTick = curTick
						end
					end
				end
			end
		end)
	end
end

function ServicesTicker:Stop()
	if self._connections then
		for _, connection in self._connections do
			connection:Disconnect()
		end
		self._connections = nil
	end
end

return ServicesTicker
